def agent(obs, config=None):
    # day*24+hour is unambiguous and present for BOTH seats; obs["step"] is
    # stripped from player 1's shared observation.
    step = int(obs.get("day", 0) or 0) * 24 + int(obs.get("hour", 0) or 0)
    if step >= len(_TAPE):
        step = len(_TAPE) - 1
    return _TAPE[step]
